#include <stdio.h>

int isPrime(int n) {
    /* TODO: n < 2 返回 0；否则用 i 从 2 试到 i * i <= n（本文件未包含 math.h，不要用 sqrt），能整除返回 0；试完返回 1。 */
    int i;
    if (n < 2) {
        return 0;
