#include <stdio.h>

int gcd(int a, int b) {
    /* TODO: 用辗转相除法求 a 与 b 的最大公约数。 */
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int lcm(int a, int b) {
    /* TODO: 先求 g = gcd(a, b)，再返回 a / g * b（先除后乘）。 */
    int g = gcd(a, b);
    if (g == 0) {
        return 0;
    }
    return a / g * b;
}

int main(void) {
    int a = 24, b = 36;   /* 演示数据：标准输入读不到时回退到这里 */
    int ina, inb;

    /* 输入格式：一行两个非负整数 a b（0 <= a, b <= 1000000，不同时为 0） */
    if (scanf("%d %d", &ina, &inb) == 2 && ina >= 0 && inb >= 0 && (ina > 0 || inb > 0)) {
        a = ina;
        b = inb;
    }

    printf("gcd=%d lcm=%d\n", gcd(a, b), lcm(a, b));
    return 0;
}

