#include <stdio.h>
#include <limits.h>

void maxAndSecond(int *a, int n, int *max1, int *max2) {
    /* TODO: 一次遍历维护最大值与次大值（注意先把 max1、max2 都置为小于所有元素的值），最后写入 *max1 和 *max2。 */
    int i;
    *max1 = INT_MIN;
    *max2 = INT_MIN;
    for (i = 0; i < n; i++) {
        if (a[i] > *max1) {
            *max2 = *max1;
            *max1 = a[i];
