#include <stdio.h>

void toUpperCopy(const char *src, char *dst) {
    /* TODO: 逐字符复制；'a'~'z' 转成大写；循环结束后在 dst 末尾补 '\0'。 */
    int i = 0;
    while (src[i] != '\0') {
        if (src[i] >= 'a' && src[i] <= 'z') {
            dst[i] = (char)(src[i] - 'a' + 'A');
        } else {
            dst[i] = src[i];
        }
        i++;
    }
    dst[i] = '\0';
}

int main(void) {
    const char *demo = "Hello, C World! 123";   /* 演示数据：标准输入读不到时回退到这里 */
    char buf[32];
    char dst[32];
