    /* 输入格式：一行字符串（含空格与数字，长度不超过 31） */
    if (fgets(buf, (int)sizeof(buf), stdin) != NULL) {
        while (buf[len] != '\0' && buf[len] != '\n' && buf[len] != '\r') {
            len++;
        }
        buf[len] = '\0';
        if (len > 0) {
            src = buf;
        }
    }

    dst[0] = '\0';
    toUpperCopy(src, dst);
    printf("%s\n", dst);
    return 0;
