#include <stdio.h>

void toBinary(int n, char *buf) {
    /* TODO: 反复取 n % 2 得到低位，倒序写入 buf，末尾补 '\0'；n 为 0 时写 "0"。 */
    char tmp[40];
    int len = 0;
    int i;
    if (n == 0) {
        buf[0] = '0';
        buf[1] = '\0';
        return;
    }
    while (n > 0) {
        tmp[len] = (char)('0' + n % 2);
        len++;
        n /= 2;
    }
    for (i = 0; i < len; i++) {
        buf[i] = tmp[len - 1 - i];
    }
    buf[len] = '\0';
}

void toHex(int n, char *buf) {
    /* TODO: 反复取 n % 16，查表 "0123456789ABCDEF" 得到十六进制字符，倒序写入 buf 并补结束符；n 为 0 时同样要写出一个 0 字符。 */
    static const char digits[] = "0123456789ABCDEF";
    char tmp[40];
    int len = 0;
    int i;
    if (n == 0) {
        buf[0] = '0';
        buf[1] = '\0';
        return;
    }
    while (n > 0) {
        tmp[len] = digits[n % 16];
        len++;
        n /= 16;
    }
    for (i = 0; i < len; i++) {
        buf[i] = tmp[len - 1 - i];
    }
    buf[len] = '\0';
