void bubbleSort(int *a, int n) {
    /* TODO: 双重循环，相邻元素比较，逆序则交换，使数组升序。 */
    int i, j;
    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j] = a[j + 1];
