    /* TODO: 维护 [low, high]，取中点比较缩小范围；找到返回下标，否则返回 -1。 */
    int low = 0;
    int high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;   /* 写成 low + (high - low) / 2 更安全 */
