#include <stdio.h>
#include <stdlib.h>

int *appendValue(int *arr, int *size, int *cap, int value) {
    /* TODO: 若 *size == *cap，用 realloc 把容量翻倍（*cap 为 0 时新容量取 4）并更新 *cap；
       把 value 存到 arr[*size]，让 *size 加 1；返回新的数组首地址。 */
    int newCap;
    int *p;

    if (*size == *cap) {
        newCap = (*cap == 0) ? 4 : *cap * 2;
        p = (int *)realloc(arr, (size_t)newCap * sizeof(int));
        if (p == NULL) {
            return arr;             /* realloc 失败：原内存仍然有效 */
        }
        arr = p;
        *cap = newCap;
    }
    arr[*size] = value;
    *size = *size + 1;
    return arr;
}

