#include <stdio.h>

#define N 4
#define MAXP 16

/* 非抢占式 SJF（短作业优先）调度
 * 参数：
 *   n            进程数
 *   arrive[]     各进程到达时间（按输入顺序非递减）
 *   service[]    各进程服务时间
 *   finish[]     输出：完成时间
 *   turnaround[] 输出：周转时间 = 完成时间 - 到达时间
 *   wturn[]      输出：带权周转时间 = 周转时间 / 服务时间
 *   order[]      输出：实际执行顺序，存放进程下标 0..n-1
 * 规则：
 *   1) 在已到达（arrive[i] <= 当前时间）且未完成的进程中，选服务时间最短者执行；
 *      服务时间相同时选下标较小者。
 *   2) 若当前没有进程到达，把当前时间直接推进到最近一个进程的到达时刻。
 *   3) 非抢占：进程一旦开始执行就运行到结束。
 * 提示：用 done[] 标记已完成进程，外层循环执行 n 次。
 * 返回值：0
 */
int sjf(int n, const int arrive[], const int service[], int finish[],
        int turnaround[], double wturn[], int order[])
{
    /* ===== TODO BEGIN ===== */
    /* TODO: 在这里实现非抢占式 SJF 调度算法 */
    int done[MAXP];
    int time = 0;
    int completed = 0;
    int i;
    int best;

    if (n <= 0) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        done[i] = 0;
    }

    while (completed < n) {
        best = -1;
        for (i = 0; i < n; i++) {
            if (done[i] || arrive[i] > time) {
                continue;
            }
            /* 服务时间相同（严格小于才替换）时保留下标较小者 */
            if (best == -1 || service[i] < service[best]) {
                best = i;
            }
        }
        if (best == -1) {
            /* 当前没有进程到达：把时间推进到最近一个未完成进程的到达时刻 */
            int next = -1;
            for (i = 0; i < n; i++) {
                if (!done[i] && (next == -1 || arrive[i] < next)) {
                    next = arrive[i];
                }
            }
            if (next == -1) {
                break;
            }
            time = next;
            continue;
        }
        time += service[best];
        finish[best] = time;
        turnaround[best] = finish[best] - arrive[best];
        wturn[best] = (double)turnaround[best] / (double)service[best];
        order[completed] = best;
        done[best] = 1;
        completed++;
    }
    return 0;
    /* ===== TODO END ===== */
}

int main(void)
{
