        return 0;
    }
    for (i = 0; i < n; i++) {
        remain[i] = service[i];
        queued[i] = 0;
    }

    while (completed < n) {
        if (head == tail) {
            /* 规则 4：就绪队列为空时，当前时间直接推进到下一个未完成进程的到达时刻 */
            int next = -1;
            for (i = 0; i < n; i++) {
                if (!queued[i] && (next == -1 || arrive[i] < next)) {
                    next = arrive[i];
                }
            }
            if (next == -1) {
                break;
