                    (pick == -1 || arrive[i] < arrive[pick])) {
                    pick = i;
                }
            }
            if (pick == -1) {
                break;
            }
            queue[tail++] = pick;
            queued[pick] = 1;
        }
        if (head == tail) {
            break;
        }

        /* 规则 2：队首进程运行 min(剩余服务时间, quantum) 个时间单位 */
        pick = queue[head++];
        run = remain[pick] < quantum ? remain[pick] : quantum;
        sched_pid[*slice_count] = pick;
        sched_start[*slice_count] = time;
        sched_end[*slice_count] = time + run;
        *slice_count = *slice_count + 1;
        time += run;
