 * 返回值：1 = 安全，0 = 不安全
 */
int bankers(int n, int m, const int avail[], const int alloc[][M], const int maxm[][M],
            int need[][M], int seq[], int wlog[][M])
{
        int work[M];        /* Work = Available，随进程执行不断累加回收的资源 */
    int finish[N];      /* Finish[i]：进程 i 是否已进入安全序列 */
    int cnt = 0;        /* 已进入安全序列的进程个数 */
    int progress = 1;   /* 本轮扫描是否有进程被执行 */

    for (int j = 0; j < m; j++) {
        work[j] = avail[j];
    }
    for (int i = 0; i < n; i++) {
        finish[i] = 0;
        for (int j = 0; j < m; j++) {
            need[i][j] = maxm[i][j] - alloc[i][j];
        }
    }

    while (progress) {
        progress = 0;
        for (int i = 0; i < n; i++) {
            if (finish[i]) {
                continue;
            }
            int enough = 1;
            for (int j = 0; j < m; j++) {
                if (need[i][j] > work[j]) {
                    enough = 0;
                    break;
                }
            }
