                    work[j] += alloc[i][j];
                    wlog[cnt][j] = work[j];
                }
                finish[i] = 1;
                seq[cnt] = i;
                cnt++;
                progress = 1;   /* 本轮有进展，本轮继续往后扫 */
            }
        }
    }

    return cnt == n ? 1 : 0;

}

