        size[chosen] -= req[i];
        remain[i] = size[chosen];
        part[i] = chosen + 1;          /* 分区号从 1 开始 */
        if (size[chosen] == 0) {
            free_flag[chosen] = 0;     /* 用完则整个分区被占用 */
        }
        cnt++;
    }

    return cnt;

}

