 *   remain[]    输出：第 i 个作业分配后该分区的剩余大小，失败为 0
 * 规则：在所有大小满足要求且空闲的分区中选择最小的一个（能装下即可，浪费最少）；
 *       分区大小相同时选择地址较小（下标较小）的分区；
 *       若分区剩余为 0 则标记该分区已占用（free_flag = 0），否则把分区大小改为剩余大小；
 *       找不到满足要求的分区则分配失败。
 * 返回值：成功分配的作业个数
 */
int best_fit(int pn, int size[], int free_flag[], const int req[], int rn,
             int part[], int remain[])
{
        int cnt = 0;   /* 成功分配的作业个数 */

    for (int i = 0; i < rn; i++) {
        int best = -1;
        /* 在所有装得下的空闲分区中选最小的一个；用严格小于比较，
           因此大小相同时保留下标较小（地址较小）的那个分区 */
        for (int j = 0; j < pn; j++) {
            if (!free_flag[j] || size[j] < req[i]) {
                continue;
            }
            if (best < 0 || size[j] < size[best]) {
                best = j;
            }
        }
        if (best < 0) {
            part[i] = -1;
            remain[i] = 0;
            continue;
        }
        size[best] -= req[i];
        remain[i] = size[best];
        part[i] = best + 1;           /* 分区号从 1 开始 */
        if (size[best] == 0) {
            free_flag[best] = 0;      /* 用完则整个分区被占用 */
        }
        cnt++;
    }

    return cnt;

}

