/* FIFO（先进先出）页面置换算法
 * 参数：
 *   frames       页框数
 *   ref[]        页面访问序列
 *   len          访问次数
 *   fault[]      输出：第 i 次访问是否缺页（1 缺页，0 命中）
 *   evict[]      输出：第 i 次访问淘汰的页面号，未淘汰为 -1
 *   state[][FRAMES] 输出：第 i 次访问后的页框内容，
 *                    下标 0 表示最早进入内存的页面，已装入页面紧凑排在前部，
 *                    未使用的页框记 -1
 *   *fault_count 输出：缺页总次数
 * 规则：
 *   1) 命中：页框内容不变（FIFO 命中不改变淘汰顺序）。
 *   2) 缺页且有空闲页框：新页面放到末尾。
 *   3) 缺页且页框已满：淘汰下标 0 的页面（最早进入内存），其余页框整体前移，
 *      再把新页面放到末尾。
 * 返回值：0
 */
int fifo(int frames, const int ref[], int len, int fault[], int evict[],
         int state[][FRAMES], int *fault_count)
{
        int frame[FRAMES];   /* 页框内容，下标小的是最早进入内存的 */
    int used = 0;        /* 已装入的页面个数（已装入页面紧凑排在前部） */

    for (int j = 0; j < FRAMES; j++) {
        frame[j] = -1;
    }
    *fault_count = 0;

    for (int i = 0; i < len; i++) {
        int page = ref[i];
        int hit = 0;
        for (int j = 0; j < used; j++) {
            if (frame[j] == page) {
                hit = 1;
                break;
            }
        }
        if (hit) {
            /* 命中：页框内容与顺序都不变 */
            fault[i] = 0;
            evict[i] = -1;
        } else {
            fault[i] = 1;
            (*fault_count)++;
            if (used < frames) {
                /* 还有空闲页框：新页面放到末尾 */
                frame[used] = page;
                used++;
                evict[i] = -1;
            } else {
                /* 页框已满：淘汰下标 0（最早进入内存），其余前移，新页面放末尾 */
                evict[i] = frame[0];
                for (int j = 0; j + 1 < frames; j++) {
                    frame[j] = frame[j + 1];
                }
                frame[frames - 1] = page;
            }
        }
        for (int j = 0; j < FRAMES; j++) {
            state[i][j] = (j < used) ? frame[j] : -1;
        }
    }

    return 0;

}

