#include <stdio.h>
#include <stdlib.h>

#define REQ 9   /* 磁盘请求个数 */

/* SSTF（最短寻道时间优先）磁盘调度
 * 参数：
 *   start       初始磁头位置
 *   req[]       磁道请求序列（只读，算法内部用 served[] 标记已访问）
 *   n           请求个数
 *   order[]     输出：实际访问顺序（磁道号）
 *   move[]      输出：第 i 次移动的磁道数（order[i] 与上一次位置之差的绝对值）
 *   *total      输出：移动的总磁道数
 * 规则：每次在尚未访问的请求中选择离当前磁头位置最近的一个；
 *       距离相同时（即左右两个请求等距）选择磁道号较小的一个。
 * 返回值：0
 */
int sstf(int start, const int req[], int n, int order[], int move[], int *total)
{
        int served[REQ] = {0};   /* served[j] = 1 表示 req[j] 已被访问 */
    int cur = start;         /* 磁头当前位置 */
    int done = 0;            /* 已访问的请求个数 */

    *total = 0;

    while (done < n) {
        int best = -1;
        for (int j = 0; j < n; j++) {
            if (served[j]) {
                continue;
            }
            if (best < 0) {
                best = j;
                continue;
            }
            int dj = abs(req[j] - cur);
            int db = abs(req[best] - cur);
            if (dj < db || (dj == db && req[j] < req[best])) {
                best = j;   /* 更近，或者等距但磁道号更小 */
            }
        }
        served[best] = 1;
        order[done] = req[best];
        move[done] = abs(req[best] - cur);
        *total += move[done];
        cur = req[best];
        done++;
    }

    return 0;

}

int main(void)
{
