 * 规则：
 *   1) 沿初始方向一直移动，依次访问该方向上所有尚未访问的请求磁道（由近到远），
 *      直到该方向上没有请求为止（不移动到磁盘端点）。
 *   2) 然后反方向移动，再依次访问反方向上所有尚未访问的请求磁道（由近到远）。
 * 返回值：0
 */
int scan_disk(int start, const int req[], int n, int direction,
              int order[], int move[], int *total)
{
        int served[REQ] = {0};   /* served[j] = 1 表示 req[j] 已被访问 */
    int cur = start;         /* 磁头当前位置 */
    int done = 0;            /* 已访问的请求个数 */

    *total = 0;

    /* 第 1 趟沿初始方向，第 2 趟沿反方向；每趟都从最近的请求开始依次服务 */
    for (int pass = 0; pass < 2; pass++) {
        int dir = (pass == 0) ? direction : !direction;
        for (;;) {
            int best = -1;
            for (int j = 0; j < n; j++) {
                if (served[j]) {
                    continue;
                }
                if (dir) {
                    /* 向磁道号增大方向：只找 >= 当前位置的请求，取最近的（最小的磁道号） */
                    if (req[j] >= cur && (best < 0 || req[j] < req[best])) {
                        best = j;
                    }
                } else {
                    /* 向磁道号减小方向：只找 <= 当前位置的请求，取最近的（最大的磁道号） */
                    if (req[j] <= cur && (best < 0 || req[j] > req[best])) {
                        best = j;
                    }
                }
            }
            if (best < 0) {
                break;   /* 该方向已无请求，换向 */
            }
            served[best] = 1;
            order[done] = req[best];
            move[done] = abs(req[best] - cur);
            *total += move[done];
            cur = req[best];
            done++;
        }
    }

    return 0;

}

