                int *produced, int *consumed)
{
        int buf[BUFSIZE];    /* 环形缓冲区，空槽用 -1 表示 */
    int in = 0;          /* 下一个放入位置 */
    int out = 0;         /* 下一个取出位置 */
    int count = 0;       /* 缓冲区中当前数据个数 */
    int next_item = 1;   /* 下一个要生产的数据编号 */
    int empty = bufsize; /* 信号量初值：empty = 缓冲区大小 */
