 *     0 = 还没有拿任何筷子（未参与本轮请求）
 *     1 = 已拿起左筷 Ci，正在等待右筷 C((i+1)%5)
 *     2 = 已拿起左右两支筷子，正在进餐（进餐结束后会放下筷子）
 * 参数：
 *   state[]    各哲学家状态
 *   chain[]    输出：死锁时的循环等待链（哲学家编号），从编号最小的哲学家开始
 *   *chain_len 输出：循环等待链的长度（不死锁时为 0）
 * 判断规则：
 *   1) 只要存在 state[i]==2 的哲学家，他最终会放下筷子，系统不会死锁，返回 0。
 *   2) 否则构造等待关系：等待中的哲学家 Pi（state[i]==1）等待右筷 C((i+1)%5)；
 *      若该筷子空闲（没有被任何 state==1 的哲学家持有），Pi 可以拿到筷子进餐，
 *      系统不会死锁，返回 0。
 *   3) 若所有等待中的哲学家都持有左筷，且等待的右筷都被别人持有，
 *      则形成环 P0 -> P1 -> P2 -> P3 -> P4 -> P0，返回 1，并把环写入 chain。
 * 返回值：1 = 死锁，0 = 不死锁
 */
int check_deadlock(const int state[], int chain[], int *chain_len)
{
        int holder[PHILO];   /* holder[k] = 持有筷子 Ck 的哲学家编号，-1 表示空闲 */
    int waiters = 0;     /* 正在等待右筷的哲学家个数 */
    int start = -1;      /* 编号最小的等待者 */

    *chain_len = 0;

    /* 规则 1：有人正在进餐，他吃完会放下筷子，等待环会被打破 */
    for (int i = 0; i < PHILO; i++) {
        if (state[i] == 2) {
            return 0;
        }
    }

    /* 构造筷子归属：state[i]==1 的哲学家 Pi 持有左筷 Ci */
    for (int i = 0; i < PHILO; i++) {
        holder[i] = -1;
    }
    for (int i = 0; i < PHILO; i++) {
        if (state[i] == 1) {
            holder[i] = i;
        }
    }

    /* 规则 2：Pi 等待右筷 C((i+1)%PHILO)，只要有一支空闲就有人能继续推进 */
    for (int i = 0; i < PHILO; i++) {
        if (state[i] != 1) {
            continue;
        }
        waiters++;
        if (start < 0) {
            start = i;
        }
        if (holder[(i + 1) % PHILO] < 0) {
            return 0;
        }
    }

    if (waiters == 0) {
        return 0;   /* 没有任何哲学家在等待，不可能有循环等待 */
    }

    /* 规则 3：每个等待者的右筷都被下一位等待者持有，形成循环等待链 */
    {
        int cur = start;
        int len = 0;
        do {
            chain[len] = cur;
            len++;
            cur = (cur + 1) % PHILO;   /* Pi 等的右筷 C(i+1) 归属 P(i+1) */
        } while (cur != start && len < PHILO);
        *chain_len = len;
    }

    return 1;

}

