int insertElement(int arr[], int *length, int position, int value) {
    if (arr == NULL || length == NULL) {
        return 0;
    }
    if (position < 0 || position > *length) {
        return 0;   /* 插入位置非法 */
    }
    if (*length >= MAX_SIZE) {
        return 0;   /* 表已满，没有容量 */
