#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

Node* append(Node *head, int value) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (node == NULL) {
        return head;
    }
    node->data = value;
    node->next = NULL;
    if (head == NULL) {
        return node;   /* 空链表：新节点就是头节点 */
    }
    Node *p = head;
    while (p->next != NULL) {
        p = p->next;   /* 走到尾节点 */
