#include <stdio.h>
#include <string.h>

#define MAX_SIZE 200

int isMatched(const char *s) {
    char stack[MAX_SIZE];
    int top = -1;
    /* 遇到左括号入栈，遇到右括号时检查栈顶是否匹配。 */
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (top + 1 >= MAX_SIZE) {
                return 0;
            }
            stack[++top] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == -1) {
                return 0;
            }
            char open = stack[top--];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return 0;
            }
        } else {
            return 0;
        }
    }
    return top == -1;
}

int main() {
    char expr[MAX_SIZE + 1];
    int hasInput = 0;

    /* 输入格式：若干只含圆括号、中括号和花括号的字符串（用空白分隔，读到 EOF 为止），
       每个字符串输出一行判定结果。
       读不到任何数据时回退到原来的演示数据。 */
    while (scanf("%200s", expr) == 1) {
        printf("%s\n", isMatched(expr) ? "matched" : "not matched");
        hasInput = 1;
    }

    if (!hasInput) {
        /* 原来的演示数据 */
        const char *demo = "{[()()]}";
        printf("%s\n", isMatched(demo) ? "matched" : "not matched");
    }
    return 0;
}

