#include <stdio.h>

#define CAPACITY 6

typedef struct {
    int data[CAPACITY];
    int front;
    int rear;
} CircularQueue;

int enqueue(CircularQueue *q, int value) {
    /* 判断队满，并使用取模运算移动 rear。 */
    if ((q->rear + 1) % CAPACITY == q->front) {
        return 0;
    }
    q->data[q->rear] = value;
    q->rear = (q->rear + 1) % CAPACITY;
    return 1;
}

int dequeue(CircularQueue *q, int *value) {
    /* 判断队空，并使用取模运算移动 front。 */
    if (q->front == q->rear) {
        return 0;
