    Node *p = a;
    Node *q = b;
    Node *head = NULL;
    Node *tail = NULL;

    while (p != NULL && q != NULL) {
        Node *src = (p->data <= q->data) ? p : q;
        Node *node = (Node *)malloc(sizeof(Node));
        node->data = src->data;
        node->next = NULL;
        if (head == NULL) {
            head = tail = node;
        } else {
