#include <stdio.h>

/* 判断只含 () [] {} 的字符串 s 是否括号匹配：匹配返回 1，否则返回 0 */
int isBalanced(const char *s) {
    /* TODO: 用一个字符数组当栈（栈顶下标 top 从 -1 开始）：
       遇到 '(' '[' '{' 就压入栈；
       遇到 ')' ']' '}' 时，若栈空或栈顶不是与之配对的左括号就返回 0，否则弹出栈顶；
       扫描结束后栈空返回 1，否则返回 0 */
    char stack[128];
    int top = -1;

    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];

        if (c == '(' || c == '[' || c == '{') {
            top++;
            stack[top] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            char need;
            if (c == ')') {
                need = '(';
            } else if (c == ']') {
                need = '[';
            } else {
                need = '{';
            }
            if (top < 0 || stack[top] != need) {
                return 0;
            }
            top--;
        }
    }

    return top < 0;
}

