    s->data[s->top] = x;
}

int sTop(const Stack *s) {
    return s->data[s->top];
}

void sPop(Stack *s) {
    s->top--;
}

int sEmpty(const Stack *s) {
    return s->top == -1;
}

typedef struct {
    Stack in;    /* 入队用的栈 */
    Stack out;   /* 出队用的栈 */
} MyQueue;

/* 初始化：已给出，无需修改 */
void myQueueInit(MyQueue *q) {
    sInit(&q->in);
    sInit(&q->out);
}

/* 入队 */
void myQueuePush(MyQueue *q, int x) {
    /* TODO: 把 x 直接压入入队栈 q->in 即可 */
    sPush(&q->in, x);
}

