#include <stdio.h>
#include <string.h>

/* 求只含 + - * / 和括号 () 的整数表达式的值，除法为整除 */
int evalExpr(const char *expr) {
    /* TODO: 使用两个栈——操作数栈 num 和运算符栈 op：
       1) 遇到数字字符时取出完整的整数压入 num；
       2) 遇到 '(' 直接压入 op；
       3) 遇到 ')' 时不断取 op 栈顶运算符做一次二元运算，直到遇到 '(' 并将其弹出；
       4) 遇到运算符时，只要 op 栈顶仍是运算符且优先级不低于当前运算符，就先做一次运算，
          然后把当前运算符压入 op（'(' 视为优先级最低）；
       5) 扫描结束后把 op 中剩余运算符依次做完，num 栈顶即为结果 */
    int num[1024];
    char op[1024];
    int ntop = -1;
    int otop = -1;
    int i = 0;

    while (expr[i] != '\0') {
        char c = expr[i];

        if (c >= '0' && c <= '9') {
            int v = 0;
            while (expr[i] >= '0' && expr[i] <= '9') {
                v = v * 10 + (expr[i] - '0');
                i++;
            }
            ntop++;
            num[ntop] = v;
            continue;
        }

        if (c == '(') {
            otop++;
            op[otop] = c;
            i++;
            continue;
        }

        if (c == ')') {
            while (otop >= 0 && op[otop] != '(') {
                int b = num[ntop];
                int a = num[ntop - 1];
                char o = op[otop];
                int r = 0;

                ntop -= 2;
                otop--;
                if (o == '+') {
                    r = a + b;
                } else if (o == '-') {
                    r = a - b;
                } else if (o == '*') {
                    r = a * b;
                } else {
                    r = a / b;
                }
                ntop++;
                num[ntop] = r;
            }
            if (otop >= 0) {
                otop--;   /* 弹出 '(' */
            }
            i++;
            continue;
        }

        /* 当前字符是 + - * /：先把栈顶优先级不低于它的运算符全部算完 */
        while (otop >= 0 && op[otop] != '(' &&
               ((op[otop] == '*' || op[otop] == '/') || (c == '+' || c == '-'))) {
            int b = num[ntop];
            int a = num[ntop - 1];
            char o = op[otop];
            int r = 0;

            ntop -= 2;
            otop--;
            if (o == '+') {
                r = a + b;
            } else if (o == '-') {
                r = a - b;
            } else if (o == '*') {
                r = a * b;
            } else {
                r = a / b;
            }
            ntop++;
            num[ntop] = r;
        }
        otop++;
        op[otop] = c;
        i++;
    }

    while (otop >= 0) {
        int b = num[ntop];
        int a = num[ntop - 1];
        char o = op[otop];
        int r = 0;

        ntop -= 2;
        otop--;
        if (o == '+') {
            r = a + b;
        } else if (o == '-') {
            r = a - b;
        } else if (o == '*') {
            r = a * b;
        } else {
            r = a / b;
        }
        ntop++;
        num[ntop] = r;
    }

    return num[ntop];
}

int main(void) {
    /* 输入格式：一行不含空格的整数表达式，只含数字、+ - * / 和圆括号 ()，例如 3+4*2-(1+5)/3。
       标准输入为空时，回退到本题的演示表达式 */
