#include <stdio.h>
#include <string.h>

/* 最长回文子串：把 s 中最长的回文子串复制到 out 中（out 至少 64 字节），并保证以 '\0' 结尾；
   若存在多个等长的最长回文子串，输出其中最先出现的那个 */
void longestPalindrome(const char *s, char *out) {
    /* TODO: 中心扩展法：分别以每个字符（奇数长度）和每两个相邻字符之间（偶数长度）为中心向两边扩展，
       记录最长回文子串的起点和长度，最后把该子串复制到 out 并补上 '\0'；
       空串时 out 应为空字符串 */
    int n = (int)strlen(s);
    int bestStart = 0;
    int bestLen = 0;

    for (int c = 0; c < n; c++) {
        int l;
        int r;

        /* 奇数长度回文：以 c 为中心 */
        l = c;
        r = c;
        while (l >= 0 && r < n && s[l] == s[r]) {
            l--;
            r++;
        }
        if (r - l - 1 > bestLen) {
            bestLen = r - l - 1;
            bestStart = l + 1;
        }

        /* 偶数长度回文：以 c 与 c+1 之间为中心 */
        l = c;
        r = c + 1;
        while (l >= 0 && r < n && s[l] == s[r]) {
            l--;
            r++;
        }
        if (r - l - 1 > bestLen) {
            bestLen = r - l - 1;
            bestStart = l + 1;
        }
    }

    for (int i = 0; i < bestLen; i++) {
        out[i] = s[bestStart + i];
    }
    out[bestLen] = '\0';
}

int main(void) {
    /* 输入格式：一行一个不含空格的字符串（长度 1 ~ 63）。
       标准输入为空时，回退到本题的演示字符串 */
    char s[64] = "abaxyzzyxf";
    char in[64];
    char out[64] = "";

    if (scanf("%63s", in) == 1 && in[0] != '\0') {
        strcpy(s, in);
    }

    longestPalindrome(s, out);
    printf("%s\n", out);
    return 0;
}

