#include <stdio.h>

#define MAXN 1024

/* 打印数组：已给出，无需修改 */
void printArray(const int *a, int n) {
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", a[i]);
    }
    printf("\n");
}

/* 向下调整：把结点 a[i] 在 a[0..n-1] 范围内调整到合适位置 */
static void siftDown(int *a, int i, int n) {
    int temp = a[i];

    while (2 * i + 1 <= n - 1) {
        int child = 2 * i + 1;

        if (child + 1 <= n - 1 && a[child + 1] < a[child]) {
            child = child + 1;
        }
        if (a[child] >= temp) {
            break;
        }
        a[i] = a[child];
        i = child;
    }
    a[i] = temp;
}

/* 建立小根堆：把数组 a[0..n-1] 原地调整成小根堆 */
void buildMinHeap(int *a, int n) {
    /* 从最后一个非叶子结点 a[n/2 - 1] 开始向前，每个结点做一次向下调整，整体为 O(n) */
    for (int i = n / 2 - 1; i >= 0; i--) {
        siftDown(a, i, n);
    }
}

/* 在已经建好的小根堆上做堆排序：排序结果按降序写回数组 a[0..n-1] */
void heapSortDesc(int *a, int n) {
    for (int end = n - 1; end >= 1; end--) {
        int t = a[0];
        a[0] = a[end];
        a[end] = t;
        siftDown(a, 0, end);
    }
}

