#include <stdio.h>

#define MAXN 1024

/* 打印数组：已给出，无需修改 */
void printArray(const int *a, int n) {
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", a[i]);
    }
    printf("\n");
}

/* 一趟划分：把 a[low..high] 以 a[low] 为基准划分，返回基准最终所在的下标 */
static int partition(int *a, int low, int high) {
    int pivot = a[low];
    int i = low;
    int j = high;

    while (i < j) {
        while (i < j && a[j] >= pivot) {
            j--;
        }
        if (i < j) {
            a[i] = a[j];
            i++;
        }
        while (i < j && a[i] <= pivot) {
            i++;
        }
        if (i < j) {
            a[j] = a[i];
            j--;
        }
    }
    a[i] = pivot;
    return i;
}

/* 快速排序：把数组 a[low..high] 原地排成升序 */
void quickSort(int *a, int low, int high) {
    if (low >= high) {
        return;
    }

    int p = partition(a, low, high);
    quickSort(a, low, p - 1);
    quickSort(a, p + 1, high);
}

