#include <stdio.h>

#define MAXV 64

/* 把 8 位有符号整数 value 转换成 8 位补码二进制字符串，写入 out。
   out 至少需要 9 个字节，最后写入 '\0'。 */
void to_twos_complement(int value, char *out)
{
    unsigned int u = (unsigned int)value & 0xFFu;
