{
    /* TODO: 先求出绝对值 mag = |value| 的低 7 位；
       value < 0 时把最高位（符号位）置 1，否则最高位保持 0。 */
    unsigned int mag;

    mag = (value < 0) ? (unsigned int)(-value) : (unsigned int)value;
    mag &= 0x7Fu;
    if (value < 0) {
        mag |= 0x80u;
    }
    return mag & 0xFFu;
}

/* 求 8 位有符号整数 value 的反码：正数与原码相同；负数为原码除符号位外按位取反。 */
unsigned int ones_complement(int value)
