#include <stdio.h>

/* 用移位相加法计算两个 8 位无符号数的乘积。
   a: 被乘数，b: 乘数，都只取低 8 位有效。
   addends[i]: 第 i 步的部分积（乘数第 i 位为 1 时是 (a 的低 8 位) << i，否则是 0）
   accs[i]   : 第 i 步累加之后累加器的值
   返回 16 位的乘积。 */
unsigned int multiply_shift_add(unsigned int a, unsigned int b,
                                unsigned int *addends, unsigned int *accs)
{
    /* TODO: 令 acc = 0，i 从 0 到 7：
       取出乘数 b 的第 i 位，若为 1 则部分积 = (a & 0xFF) << i，否则部分积 = 0；
