char even_parity(const char *bits, int len)
{
    /* TODO: 统计 '1' 的个数并返回偶校验位字符 */
    int i;
    int ones = 0;

    for (i = 0; i < len; i++) {
        if (bits[i] == '1') {
            ones++;
        }
    }
    return (ones % 2 == 1) ? '1' : '0';
}

/* 构造 (ROWS+1) 行 x (COLS+1) 列的二维偶校验矩阵
 * src  : ROWS 行，每行是 COLS 个 '0'/'1' 字符（字符串）
 * dst  : 每行可存放 COLS+1 个字符（外加 '\0'），共 ROWS+1 行
 * 要求: dst[i][j] = src[i][j]                (i<ROWS, j<COLS)
 *       dst[i][COLS]      = 第 i 行的偶校验位 (i<ROWS)
 *       dst[ROWS][j]      = 第 j 列的偶校验位 (j<COLS)
 *       dst[ROWS][COLS]   = 第 ROWS 行前 COLS 个位的偶校验位（也等于第 COLS 列前 ROWS 个位的偶校验位）
