unsigned int ip_to_int(const char *ip)
{
    /* TODO: 解析 a.b.c.d 四个十进制数并拼成 32 位整数 */
    unsigned int a = 0;
    unsigned int b = 0;
    unsigned int c = 0;
    unsigned int d = 0;

    if (sscanf(ip, "%u.%u.%u.%u", &a, &b, &c, &d) != 4)
        return 0;
    if (a > 255u || b > 255u || c > 255u || d > 255u)
        return 0;
    return (a << 24) | (b << 16) | (c << 8) | d;
}

/* 把 32 位无符号整数还原成点分十进制字符串，写入 out */
void int_to_ip(unsigned int v, char *out)
{
    /* TODO: 按 "%u.%u.%u.%u" 格式写入 out */
    sprintf(out, "%u.%u.%u.%u",
            (v >> 24) & 0xFFu, (v >> 16) & 0xFFu,
            (v >> 8) & 0xFFu, v & 0xFFu);
}

/* 由 IP 地址与前缀长度计算子网信息：
 * mask   : 子网掩码的点分十进制字符串
 * net    : 网络地址的点分十进制字符串
 * bcast  : 广播地址的点分十进制字符串
