#include <stdio.h>

#define MAX_FRAG 8
#define IP_HDR  20

/* IP 分片计算：
 * total_len : 原 IP 数据报总长度（含 20 字节首部）
 * mtu       : 链路 MTU
 * flen[i]   : 第 i 片的总长度（含 20 字节首部）
 * foff[i]   : 第 i 片的片偏移（以 8 字节为单位）
 * fmf[i]    : 第 i 片的 MF 标志，后面还有分片为 1，最后一片为 0
 * 返回分片数。注意除最后一片外，每片的数据部分必须是 8 字节的整数倍，
 * 因此每片最多携带 ((mtu - 20) / 8) * 8 字节数据。
 */
int ip_fragment(int total_len, int mtu, int flen[], int foff[], int fmf[])
{
    /* TODO: 按 8 字节对齐切分数据部分，逐片填写长度、片偏移和 MF */
    int hdr = IP_HDR;
    int payload;
    int unit;
    int sent = 0;
    int idx = 0;

    if (total_len <= hdr || mtu <= hdr)
        return 0;                         /* 无需分片或参数非法 */

    payload = total_len - hdr;
    unit = ((mtu - hdr) / 8) * 8;         /* 每片可携带的最大 8 字节对齐数据量 */
    if (unit <= 0)
        return 0;                         /* MTU 太小，无法承载任何分片数据 */

    while (sent < payload && idx < MAX_FRAG) {
        int remain = payload - sent;
        int take = (remain > unit) ? unit : remain;    /* 最后一片允许不足 8 字节 */

        flen[idx] = take + hdr;
        foff[idx] = sent / 8;
        fmf[idx] = (sent + take < payload) ? 1 : 0;
        sent += take;
        idx++;
    }
    return idx;
}

