#include <stdio.h>
#include <stdint.h>

#define TCP_HDR 20

/* 16 位反码求和：
 * 把 data 按 16 位字（大端）累加，进位回卷加到低位，返回累加结果（未取反）。
 * len 为字节数，要求为偶数。
 */
uint16_t ones_complement_sum(const uint8_t *data, int len)
{
    /* TODO: 按 16 位字累加 + 进位回卷 */
    uint32_t sum = 0;
    int i;

    for (i = 0; i + 1 < len; i += 2)
        sum += ((uint32_t)data[i] << 8) | (uint32_t)data[i + 1];
    if (len & 1)
        sum += (uint32_t)data[len - 1] << 8;

    while (sum >> 16)
        sum = (sum & 0xFFFFu) + (sum >> 16);

    return (uint16_t)sum;
}

/* 计算 TCP 校验和（含 12 字节伪首部）：
 * 伪首部 = 源 IP(4) + 目的 IP(4) + 全 0(1) + 协议号 6(1) + TCP 长度(2)
 * 把伪首部与整个 TCP 报文段（首部 + 数据）一起做 16 位反码求和，再取反。
 * 注意：TCP 首部的校验和字段按其当前值参与累加，第一次计算前置 0x0000。
 */
uint16_t tcp_checksum(const uint8_t *src_ip, const uint8_t *dst_ip,
                      const uint8_t *tcp, int tcp_len)
{
    /* TODO: 拼出伪首部 -> 与 TCP 报文段一起反码求和 -> 取反 */
    uint32_t sum;
    uint8_t pseudo[12];
    int i;

    for (i = 0; i < 4; i++) {
        pseudo[i] = src_ip[i];
        pseudo[4 + i] = dst_ip[i];
    }
    pseudo[8] = 0;                        /* 全 0 字段 */
    pseudo[9] = 6;                        /* 协议号 TCP = 6 */
    pseudo[10] = (uint8_t)((tcp_len >> 8) & 0xFF);
    pseudo[11] = (uint8_t)(tcp_len & 0xFF);

    sum = (uint32_t)ones_complement_sum(pseudo, 12);
    sum += (uint32_t)ones_complement_sum(tcp, tcp_len);

    while (sum >> 16)
        sum = (sum & 0xFFFFu) + (sum >> 16);

    return (uint16_t)(~sum & 0xFFFFu);
