#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* 解析 URL，拆出协议、主机、端口、路径：
 * url    : 待解析的 URL，形如 scheme://host[:port][/path]
 * scheme : 输出协议名（http / https / ftp ...）
 * host   : 输出主机名
 * port   : 输出端口号；URL 中没有显式端口时填默认端口
 *          （http -> 80，https -> 443，其它协议 -> 0）
 * path   : 输出路径（以 '/' 开头）；URL 中没有路径时输出 "/"
 */
void parse_url(const char *url, char *scheme, char *host, int *port, char *path)
{
    /* TODO: 定位 "://"、':'、'/'，分别取出协议、主机、端口、路径 */
    const char *p = strstr(url, "://");
    const char *hp;
    const char *end;
    size_t n;
    int default_port = 0;

    scheme[0] = '\0';
    host[0] = '\0';
    path[0] = '\0';
    *port = 0;
    if (p == NULL)
        return;

    n = (size_t)(p - url);
    if (n > 15)
        n = 15;
    memcpy(scheme, url, n);
    scheme[n] = '\0';

    hp = p + 3;                                    /* 主机部分起始位置 */
    end = hp;
    while (*end != '\0' && *end != '/' && *end != ':')
        end++;                                     /* 主机名结束位置 */

    n = (size_t)(end - hp);
    if (n > 127)
        n = 127;
    memcpy(host, hp, n);
    host[n] = '\0';

    if (strcmp(scheme, "http") == 0)
        default_port = 80;
    else if (strcmp(scheme, "https") == 0)
        default_port = 443;

    if (*end == ':') {
        *port = atoi(end + 1);                     /* 显式端口 */
        while (*end != '\0' && *end != '/')
            end++;
        if (*port == 0)
            *port = default_port;                  /* 形如 host:/path，按默认端口处理 */
    } else {
        *port = default_port;
    }

    if (*end == '/')
        strcpy(path, end);                         /* 第一个 '/' 及其之后都是路径 */
    else
        strcpy(path, "/");                         /* 没有路径时补 "/" */
}

int main(void)
{
    /* 演示数据：从标准输入读不到数据时使用 */
