        "ftp://files.hust.edu.cn:2121/pub/data.txt"
    };

    char urls[3][256] = {{0}};
    int url_cnt = 0;
    int i;

    /* 输入格式：第一行为 URL 个数 n（1 <= n <= 3），随后 n 行每行一个 URL，
     * 形如 scheme://host[:port][/path] */
    if (scanf("%d", &url_cnt) == 1 && url_cnt >= 1 && url_cnt <= 3) {
        for (i = 0; i < url_cnt; i++) {
            if (scanf("%255s", urls[i]) != 1) {
                url_cnt = 0;
                break;
            }
        }
    } else {
        url_cnt = 0;
    }

    if (url_cnt == 0) {
        /* 回退到演示数据 */
        url_cnt = 3;
        for (i = 0; i < 3; i++)
            strcpy(urls[i], demo_urls[i]);
    }

    for (i = 0; i < url_cnt; i++) {
        char scheme[16] = {0};
        char host[128] = {0};
