#include <stdio.h>

/* 二进制指数退避（CSMA/CD）：
 * 第 i 次冲突后，从 {0, 1, ..., 2^k - 1} 中随机取整数 r，退避时间 = r * 争用期 2τ，
 * 其中 k = min(i, 10)。
 */

/* 返回第 i 次冲突时的退避窗口指数 k = min(i, 10) */
int backoff_k(int i)
{
    /* TODO: 取 i 与 10 的较小值 */
    return (i < 10) ? i : 10;
}

/* 返回第 i 次冲突时可取的最大随机数 r_max = 2^k - 1 */
long backoff_rmax(int i)
{
    /* TODO: 由 backoff_k(i) 算出 2^k - 1 */
    return (1L << backoff_k(i)) - 1L;
}

